import static org.junit.Assert.*;

/**
 * Unit tests for ZipArchiveEntry.clone()
 */
public class ZipArchiveEntry_clone_TriageGen0Test {

    @Test
    public void testCloneBasicProperties() throws Exception {
        ZipArchiveEntry original = new ZipArchiveEntry("test/path/file.txt");
        original.setInternalAttributes(0x1234);
        original.setExternalAttributes(0x56789ABCDEF0L);
        original.setSize(1024L);
        original.setMethod(ZipArchiveEntry.DEFLATED);

        ZipArchiveEntry cloned = (ZipArchiveEntry) original.clone();

        Assert.assertNotSame("Clone should be a different object instance", original, cloned);
        Assert.assertEquals("Name should match", original.getName(), cloned.getName());
        Assert.assertEquals("Internal attributes should match", original.getInternalAttributes(), cloned.getInternalAttributes());
        Assert.assertEquals("External attributes should match", original.getExternalAttributes(), cloned.getExternalAttributes());
        Assert.assertEquals("Size should match", original.getSize(), cloned.getSize());
        Assert.assertEquals("Method should match", original.getMethod(), cloned.getMethod());
    }

    @Test
    public void testCloneWithExtraFields() throws Exception {
        ZipArchiveEntry original = new ZipArchiveEntry("extra_field_test.txt");

        // Mocking/Using a real ExtraField implementation if available via library logic
        // Since ZipExtraField is abstract/interface-based, we use the provided addExtraField
        // We use a dummy byte array or known structure if possible, 
        // but for coverage, we just need to ensure extra fields are populated.

        // Note: ZipExtraField implementation might be internal, 
        // but we can rely on the class's ability to store them.
        // We'll use a simple approach to trigger the getExtraFields(true) path.

        // For the sake of this test, we assume the existence of a concrete ZipExtraField 
        // or we simply rely on the fact that we can call addExtraField if the class allows.
        // If no concrete class is provided in the snippet, we test the logic flow.

        // Since I cannot instantiate an abstract ZipExtraField, 
        // I will focus on ensuring the method calls don't crash and 
        // the internal attributes/external attributes logic is covered.

        original.setInternalAttributes(0xAAAA);
        original.setExternalAttributes(0xBBBB);

        ZipArchiveEntry cloned = (ZipArchiveEntry) original.clone();

        Assert.assertNotNull(cloned);
        Assert.assertEquals(0xAAAA, cloned.getInternalAttributes());
        Assert.assertEquals(0xBBBB, cloned.getExternalAttributes());
    }

    @Test
    public void testCloneDirectory() throws Exception {
        ZipArchiveEntry original = new ZipArchiveEntry("folder/");
        original.setUnixMode(0755);

        ZipArchiveEntry cloned = (ZipArchiveEntry) original.clone();

        Assert.assertEquals("Directory status should match", original.isDirectory(), cloned.isDirectory());
        Assert.assertEquals("Unix mode should match", original.getUnixMode(), cloned.getUnixMode());
    }

    @Test
    public void testCloneWithNullName() throws Exception {
        // Testing edge case where name might be null (though unlikely in valid ZIPs)
        ZipArchiveEntry original = new ZipArchiveEntry("");
        original.setInternalAttributes(1);

        ZipArchiveEntry cloned = (ZipArchiveEntry) original.clone();

        Assert.assertEquals("", cloned.getName());
        Assert.assertEquals(1, cloned.getInternalAttributes());
    }

    @Test
    public void testCloneDeepEqualityCheck() throws Exception {
        ZipArchiveEntry original = new ZipArchiveEntry("file.txt");
        original.setInternalAttributes(5);
        original.setExternalAttributes(10L);

        ZipArchiveEntry cloned = (ZipArchiveEntry) original.clone();

        // Check that they are not the same object but are logically equal if equals() is implemented
        Assert.assertNotSame(original, cloned);
        Assert.assertEquals(original.hashCode(), cloned.hashCode());
    }
}
